_sk_msg_lookup_unix_script() {
  case "$1" in
    '1Panel is Linux-only. Current: ') printf '%s' '1Panel 仅支持 Linux。当前：' ;;
    'systemctl (systemd) is required.') printf '%s' '需要 systemctl（systemd）。' ;;
