    'View panel address, security entry and account (1pctl user-info)') printf '%s' '查看面板地址、安全入口与账号（1pctl user-info）' ;;
    'Upgrade 1Panel (1pctl update)') printf '%s' '升级 1Panel（1pctl update）' ;;
    'Uninstall 1Panel (keep data directory)') printf '%s' '卸载 1Panel（保留数据目录）' ;;
    'View status') printf '%s' '查看状态' ;;
    'Unknown action: ') printf '%s' '未知操作: ' ;;
    'BT Panel is Linux-only. Current: ') printf '%s' '宝塔面板仅支持 Linux。当前：' ;;
    'Detected existing Web/database environment running: ') printf '%s' '检测到既有 Web/数据库环境在运行：' ;;
    'BT Panel officially requires a clean system (it installs its own Nginx/Apache/MySQL/PHP, which may conflict with existing services).') printf '%s' '宝塔官方要求在纯净系统上安装（会自建 Nginx/Apache/MySQL/PHP，易端口冲突）。' ;;
    'Still continue installing BT Panel'\?) printf '%s' '仍要继续安装宝塔面板？' ;;
    'Running official installer (takes about 2 minutes)...') printf '%s' '执行官方安装脚本（耗时约 2 分钟）...' ;;
