    'BT Panel is not installed, nothing to uninstall.') printf '%s' '宝塔面板未安装，无需卸载。' ;;
    'Will stop the panel and delete: /etc/init.d/bt, bt command, /www/server/panel (panel and software environment).') printf '%s' '将停止面板并删除：/etc/init.d/bt、bt 命令、/www/server/panel（面板与软件环境）。' ;;
    'Site data /www/wwwroot, logs /www/wwwlogs and database directories are kept by default.') printf '%s' '站点数据 /www/wwwroot、日志 /www/wwwlogs 与数据库目录默认保留。' ;;
