    'Uninstall panel (site data kept by default, /www can be deleted after second confirmation)') printf '%s' '卸载面板（站点数据默认保留，二次确认后可选删除 /www）' ;;
    'buildah %s is already installed, reinstall'\?) printf '%s' '已检测到 buildah %s，是否重新安装？' ;;
