    'buildah - OCI image build tool (Linux only)') printf '%s' 'buildah —— OCI 镜像构建工具（仅 Linux）' ;;
    'Install buildah via system repositories') printf '%s' '通过系统仓库安装 buildah' ;;
    'Uninstall (user container storage kept by default, deletion needs second confirmation)') printf '%s' '卸载（用户容器存储默认保留，删除需二次确认）' ;;
