    '🔴 Found %s bad blocks! Back up data; check disk smart %s for trends') printf '%s' '🔴 发现 %s 个坏块！建议：① 立即备份重要数据 ② ./install.sh disk smart %s 查看重映射趋势 ③ 评估更换硬盘' ;;
