    'About to configure the NTP servers: %s') printf '%s' '即将配置 NTP 服务器: %s' ;;
    'Continue'\?) printf '%s' '确认继续？' ;;
    '🕐 Setting the timezone to %s and enabling time synchronization') printf '%s' '🕐 设置时区为 %s 并启用时间同步' ;;
    'The timezone has been set to %s') printf '%s' '时区已设置为 %s' ;;
    'systemd-timesyncd (NTP) has been enabled') printf '%s' '已启用 systemd-timesyncd (NTP)' ;;
    'The timezone has been set to %s (symlink)') printf '%s' '时区已设置为 %s（符号链接）' ;;
    'chrony time synchronization has been installed and enabled') printf '%s' '已安装并启用 chrony 时间同步' ;;
    'Installing chrony failed, skipping the time synchronization setup') printf '%s' 'chrony 安装失败，跳过时间同步服务配置' ;;
    '⚙️  Optimizing the system parameters (file descriptors, kernel)') printf '%s' '⚙️  优化系统参数（文件描述符、内核）' ;;
    'The file descriptor limit has been raised to 65536 (%s)') printf '%s' '已提升文件描述符上限到 65536（%s）' ;;
    'The kernel optimization parameters have been written (%s)') printf '%s' '已写入内核优化参数（%s）' ;;
    '🔐 SSH hardening (disable password login and root login)') printf '%s' '🔐 SSH 加固（禁用密码登录、禁用 root 直登）' ;;
    'SSH hardening is sensitive: password and root login will be disabled.') printf '%s' 'SSH 加固是敏感操作：将禁用密码登录与 root 直登。' ;;
    'Set up SSH key login first, otherwise you may not be able to log in!') printf '%s' '请确保你已配置好 SSH 密钥登录，否则可能无法登录服务器！' ;;
    'Continue (only if the key login is already set up)'\?) printf '%s' '确认继续（仅当你已配置好密钥登录）？' ;;
    'SSH hardening has been skipped') printf '%s' '已跳过 SSH 加固' ;;
    'The SSH hardening configuration has been written (%s)') printf '%s' '已写入 SSH 加固配置（%s）' ;;
    'sshd has been reloaded (the configuration applies to new connections)') printf '%s' 'sshd 已 reload（配置在新连接生效）' ;;
    '🛡️  Enabling the automatic security updates') printf '%s' '🛡️  启用自动安全更新' ;;
    'Unsupported distribution (unknown family), skipping the auto update') printf '%s' '暂不支持该发行版（族未知），跳过自动更新配置' ;;
    '🚀 Running all the essential system setups') printf '%s' '🚀 执行全部装机必设置' ;;
    '🎉 All the essential system setups are complete') printf '%s' '🎉 全部装机必设置执行完成' ;;
    'Default source') printf '%s' '默认源' ;;
    'Domestic mirror source in use') printf '%s' '已换国内源' ;;
    '(system default)') printf '%s' '(系统默认)' ;;
    '(chrony, view with chronyc sources)') printf '%s' '(chrony，用 chronyc sources 查看)' ;;
    '(ntpd, view with ntpq -p)') printf '%s' '(ntpd，用 ntpq -p 查看)' ;;
    'Default') printf '%s' '默认' ;;
    '✅ Optimized') printf '%s' '✅ 已优化' ;;
    '✅ Hardened') printf '%s' '✅ 已加固' ;;
    '✅ The system configuration is complete') printf '%s' '✅ 系统配置已完成' ;;
    '⚠️  The system configuration is not complete') printf '%s' '⚠️  系统配置未完成' ;;
    'Package source mirror:') printf '%s' '软件源镜像:' ;;
    '✅ Domestic mirror source in use') printf '%s' '✅ 已换国内源' ;;
    '⚠️  Default source') printf '%s' '⚠️  默认源' ;;
    'Timezone: %s') printf '%s' '时区: %s' ;;
    'NTP sync: %s') printf '%s' 'NTP 同步: %s' ;;
    'NTP servers: %s') printf '%s' 'NTP 服务器: %s' ;;
    'File descriptor limit: %s') printf '%s' '文件描述符上限: %s' ;;
    'SSH hardening: %s') printf '%s' 'SSH 加固: %s' ;;
    'Switch to domestic mirrors (Alma/Rocky/Fedora/openEuler/Anolis/deepin)') printf '%s' '更换软件源为国内镜像（预览确认后执行；Alma/Rocky/Fedora/openEuler/Anolis/deepin 已支持）' ;;
    'Set the timezone and enable NTP sync (default Asia/Shanghai)') printf '%s' '设置时区并启用 NTP 时间同步（默认 Asia/Shanghai）' ;;
    'Configure custom NTP servers (Aliyun/TUNA/Huawei/Google/custom)') printf '%s' '配置自定义 NTP 服务器（阿里云/清华/华为/Google/自定义）' ;;
    'Optimize system parameters (file descriptors, TCP, kernel)') printf '%s' '优化系统参数（文件描述符、TCP、内核）' ;;
    'SSH hardening (disable password and root login, set up keys first)') printf '%s' 'SSH 加固（禁用密码登录、禁用 root 直登，需先配好密钥）' ;;
    'Enable the automatic security updates') printf '%s' '启用自动安全更新' ;;
    'Run all of the above') printf '%s' '依次执行以上全部' ;;
    'View the status of each configuration') printf '%s' '查看各项配置状态' ;;
    'The sys-setup uninstall only applies to Linux, nothing to do here') printf '%s' 'sys-setup 的卸载仅适用 Linux（drop-in 配置为 Linux 路径），当前平台无需卸载' ;;
    'Removing the incremental drop-in configs written by sys-setup...') printf '%s' '卸载 sys-setup 写入的增量配置（drop-in）...' ;;
    'Removed: %s') printf '%s' '已移除：%s' ;;
    'No sys-setup drop-in config found (optimize/ssh may not have run)') printf '%s' '未发现 sys-setup 写入的 drop-in 配置（可能未执行过 optimize/ssh）' ;;
    'Removed %s drop-in configurations, the system defaults are restored') printf '%s' '已移除 %s 个 drop-in 配置，系统已恢复默认值' ;;
    'The mirror/NTP changes have .bak.'\*' backups, find them to restore:') printf '%s' '镜像源/NTP 等修改在安装时已生成 .bak.* 备份，如需还原请手动查找：' ;;
    'The SSH service policy is restored, review it if you changed sshd: %s') printf '%s' 'SSH 服务策略已恢复默认，如修改过 sshd 建议复查：%s' ;;
    'Back up /etc/apk/repositories') printf '%s' '备份 /etc/apk/repositories' ;;
    'Rewrite to Tsinghua TUNA (v%s main + community)') printf '%s' '重写为清华 TUNA（v%s main + community）' ;;
    'The Alpine source has been replaced by the Tsinghua mirror') printf '%s' 'Alpine 源已替换为清华镜像' ;;
    'No native automatic security updates in Alpine, run sudo apk upgrade') printf '%s' 'Alpine 无原生自动安全更新；建议定期执行 sudo apk upgrade' ;;
    'Back up /etc/pacman.d/mirrorlist') printf '%s' '备份 /etc/pacman.d/mirrorlist' ;;
    'Rewrite to Tsinghua TUNA (%s · %s path)') printf '%s' '重写为清华 TUNA（%s · %s 路径）' ;;
    '%s: no known mirror path, guidance only (no system change)') printf '%s' '%s 暂无把握的镜像路径，仅打印指引（不改动系统）' ;;
    '%s · %s: no known mirror path, mirrorlist is left unchanged') printf '%s' '%s · %s 暂无把握的镜像路径，保持 mirrorlist 不变' ;;
    '%s mirrorlist has been replaced by the Tsinghua mirror (%s path)') printf '%s' '%s mirrorlist 已替换为清华镜像（%s 路径）' ;;
    'Arch is rolling release, run sudo pacman -Syu to stay updated') printf '%s' 'Arch 为滚动发布，建议定期执行 sudo pacman -Syu 保持更新' ;;
    'Failed to disable it (permissions'\?'): %s') printf '%s' '停用失败（权限？）：%s' ;;
    'Disabled the duplicate source file: %s (restore: sudo mv %s.bak.%s %s)') printf '%s' '已停用重复/残留源文件：%s（恢复：sudo mv %s.bak.%s %s）' ;;
    'Back up and rewrite %s to Tsinghua TUNA (%s/%s)') printf '%s' '备份并重写 %s 为清华 TUNA（%s/%s）' ;;
    'Disable the other distro archive apt sources (rename to '\*'.bak.<ts>)') printf '%s' '停用其余发行版归档 apt 源（重命名 *.bak.<ts>，可随时恢复）' ;;
    'Rewrite sources.list to Tsinghua TUNA (%s/%s, main community)') printf '%s' '备份并重写 /etc/apt/sources.list 为清华 TUNA（%s/%s，main community）' ;;
    'Disable the remaining distribution archive apt sources') printf '%s' '停用其余发行版归档 apt 源' ;;
    '%s: no public mirror repository, guidance only (no system change)') printf '%s' '%s 暂无公开镜像仓库，仅打印指引（不改动系统）' ;;
    'Unable to identify the distribution codename (VERSION_CODENAME)') printf '%s' '无法识别发行版代号（VERSION_CODENAME）' ;;
    'apt source switched to Tsinghua mirror (%s/%s), original file backed up') printf '%s' 'apt 源已更换为清华镜像（%s/%s），原文件已备份' ;;
    'apt source switched to the Tsinghua mirror (%s/%s)') printf '%s' 'apt 源已更换为清华镜像（%s/%s）' ;;
    'Kylin/openKylin has no public mirror, the system sources are kept') printf '%s' '银河麒麟/openKylin 暂无公开镜像仓库，保持系统源不变' ;;
    'To switch the mirrors, use the built-in source tool or the server docs') printf '%s' '如需换源请使用系统自带「软件源」工具或参考服务器版官方文档' ;;
    '%s automatic security updates are handled by the system updater') printf '%s' '%s 的自动安全更新由系统更新器管理，跳过' ;;
    'Enabled Debian/Ubuntu/Mint auto security updates (unattended-upgrades)') printf '%s' '已启用 Debian/Ubuntu/Mint 自动安全更新（unattended-upgrades）' ;;
    'Back up /etc/yum.repos.d') printf '%s' '备份 /etc/yum.repos.d' ;;
    'Rewrite centos.repo to Tsinghua TUNA (CentOS Stream)') printf '%s' '重写 centos.repo 为清华 TUNA（CentOS Stream）' ;;
    'Rewrite almalinux.repo to point to the Aliyun mirror') printf '%s' '整写 almalinux.repo 指向阿里云镜像（BaseOS/AppStream/CRB/extras）' ;;
    'Rewrite rocky.repo to point to the USTC mirror (major version path)') printf '%s' '整写 rocky.repo 指向中科大 USTC 镜像（BaseOS/AppStream/CRB/Extras，主版本路径）' ;;
    'Rewrite fedora.repo and fedora-updates.repo to point to Tsinghua TUNA') printf '%s' '整写 fedora.repo 与 fedora-updates.repo 指向清华 TUNA' ;;
    'sed: replace the openEuler sources with Tsinghua TUNA') printf '%s' 'sed 将 mirror.openeuler.org / repo.openeuler.org 替换为清华 TUNA（保留原 repo 结构）' ;;
    'sed: replace the openAnolis sources with the Aliyun mirror') printf '%s' 'sed 将 openanolis / anolis 官方源替换为阿里云镜像（保留原 repo 结构）' ;;
    '%s: no public mirror, guidance only (no system change)') printf '%s' '%s 暂无公开镜像，仅打印指引（不改动系统）' ;;
    'CentOS Stream source switched to the Tsinghua mirror (repos backed up)') printf '%s' 'CentOS Stream 源已更换为清华镜像（原 /etc/yum.repos.d 已备份）' ;;
    'CentOS 7/8 (EOL) refer to the vault: %s') printf '%s' 'CentOS 7/8（EOL）请参考 vault：%s' ;;
    'Original /etc/yum.repos.d backed up to .bak.%s, replace baseurl') printf '%s' '已备份原 /etc/yum.repos.d 到 /etc/yum.repos.d.bak.%s，请按指引手动替换 baseurl' ;;
    'AlmaLinux source switched to the Aliyun mirror (repos.d backed up)') printf '%s' 'AlmaLinux 源已更换为阿里云镜像（原 /etc/yum.repos.d 已备份）' ;;
    'Rocky Linux source switched to the USTC mirror (repos.d backed up)') printf '%s' 'Rocky Linux 源已更换为中科大镜像（原 /etc/yum.repos.d 已备份）' ;;
    'Fedora source switched to the Tsinghua mirror (repos.d backed up)') printf '%s' 'Fedora 源已更换为清华镜像（原 /etc/yum.repos.d 已备份）' ;;
    'openEuler source replaced by the Tsinghua mirror (repos backed '\*'.bak)') printf '%s' 'openEuler 源已替换为清华镜像（原 repo 已备份 *.bak）' ;;
    'Anolis OS source replaced by the Aliyun mirror (repos backed up '\*'.bak)') printf '%s' 'Anolis OS 源已替换为阿里云镜像（原 repo 已备份 *.bak）' ;;
    'RHEL/Kylin (server) has no public mirror, the system sources are kept') printf '%s' 'RHEL/麒麟(服务器) 无公开镜像（订阅授权），保持系统源不变' ;;
    'RHEL: use subscription-manager; Kylin: use the built-in update source') printf '%s' 'RHEL 请使用订阅管理（subscription-manager）；麒麟请使用系统自带更新源' ;;
    'dnf-automatic has been enabled') printf '%s' '已启用 dnf-automatic' ;;
    'yum-cron has been enabled') printf '%s' '已启用 yum-cron' ;;
    'Back up /etc/zypp/repos.d') printf '%s' '备份 /etc/zypp/repos.d' ;;
    'sed: replace download.opensuse.org with Tsinghua TUNA') printf '%s' 'sed 将 download.opensuse.org 替换为清华 TUNA（保留原 repo 结构）' ;;
    'openSUSE source replaced by the Tsinghua mirror (repos.d backed up)') printf '%s' 'openSUSE 源已替换为清华镜像（原 /etc/zypp/repos.d 已备份）' ;;
    'openSUSE: use yast2 online_update, or run sudo zypper patch regularly') printf '%s' 'openSUSE 建议用 yast2 online_update 配置自动补丁；或定期执行 sudo zypper patch' ;;
    '🧠 Installing Ollama (the local large model runtime)') printf '%s' '🧠 安装 Ollama（本地大模型运行时）' ;;
    'Ollama detected (%s)') printf '%s' '检测到已安装 Ollama（%s）' ;;
    'Installing ollama via Homebrew...') printf '%s' '通过 Homebrew 安装 ollama...' ;;
    'Homebrew is required, or download the app from https://ollama.com/download') printf '%s' '需要 Homebrew，或从 https://ollama.com/download 下载 app' ;;
    'Installing with the official script (including the systemd service)...') printf '%s' '通过官方脚本安装（含 systemd 服务）...' ;;
    'The official installation script failed, see https://github.com/ollama/ollama') printf '%s' '官方安装脚本执行失败，请参考 https://github.com/ollama/ollama' ;;
    'ollama was not found after the installation, reopen the terminal or check PATH') printf '%s' '安装后仍找不到 ollama，请重新打开终端或检查 PATH' ;;
    '🎉 Ollama installation complete!') printf '%s' '🎉 Ollama 安装完成！' ;;
    'Download and run a model (the first pull is slow)') printf '%s' '下载并运行模型（首次拉取较慢）' ;;
    'Download the model only') printf '%s' '仅下载模型' ;;
    'The model has been downloaded') printf '%s' '已下载模型' ;;
    'Start the API service (port 11434 by default)') printf '%s' '启动 API 服务（默认 11434 端口）' ;;
    'Common models: qwen3:8b / llama3.2 / deepseek-r1 / gemma3') printf '%s' '常用模型：qwen3:8b / llama3.2 / deepseek-r1 / gemma3' ;;
    'Model library: https://ollama.com/library') printf '%s' '模型库：https://ollama.com/library' ;;
    'Pulling the model: %s') printf '%s' '拉取模型：%s' ;;
    'The model %s is ready, run it with ollama run %s') printf '%s' '模型 %s 已就绪，用 '\''ollama run %s'\'' 启动' ;;
    'ollama has been uninstalled (macOS)') printf '%s' '已卸载 ollama（macOS）' ;;
    'Uninstall Ollama'\?) printf '%s' '确认卸载 Ollama？' ;;
    'Delete all the downloaded models (~/.ollama, it may be large)'\?) printf '%s' '是否删除所有已下载模型（~/.ollama，可能很大）？' ;;
    'The model data has been deleted') printf '%s' '模型数据已删除' ;;
    'Install Ollama (the local large model runtime)') printf '%s' '安装 Ollama（本地大模型运行时）' ;;
    'model>     pull a model (qwen3:8b by default)') printf '%s' '模型>     拉取模型（默认 qwen3:8b）' ;;
    'Uninstall (optionally delete the downloaded models)') printf '%s' '卸载（可选删除已下载模型）' ;;
    '🤖 Installing OpenCode (the terminal AI coding assistant)') printf '%s' '🤖 安装 OpenCode（终端 AI 编程助手）' ;;
    'OpenCode detected (%s)') printf '%s' '检测到已安装 OpenCode（%s）' ;;
    'Installing opencode via Homebrew...') printf '%s' '通过 Homebrew 安装 opencode...' ;;
    'Installing with the official script (%s)...') printf '%s' '通过官方脚本安装（%s）...' ;;
    'The official installation script failed, check the network or see https://opencode.ai/docs/') printf '%s' '官方安装脚本执行失败，请检查网络或参考 https://opencode.ai/docs/' ;;
    'It has been installed to ~/.local/bin/opencode, but it is not in the current PATH') printf '%s' '已装到 ~/.local/bin/opencode，但不在当前 PATH' ;;
    'Please add it to your shell configuration: export PATH="%s/.local/bin:$PATH"') printf '%s' '请添加到 shell 配置：export PATH="%s/.local/bin:$PATH"' ;;
    'opencode was not found after the installation, reopen the terminal or check PATH') printf '%s' '安装后仍找不到 opencode，请重新打开终端或检查 PATH' ;;
    '🎉 OpenCode installation complete!') printf '%s' '🎉 OpenCode 安装完成！' ;;
    'Start an AI coding session in the project directory') printf '%s' '在项目目录启动 AI 编程会话' ;;
    'Configure the model / API key: see https://opencode.ai/docs/') printf '%s' '配置模型/API Key：参考 https://opencode.ai/docs/' ;;
    'opencode has been uninstalled via brew') printf '%s' '已通过 brew 卸载 opencode' ;;
    'The opencode binary has been deleted') printf '%s' '已删除 opencode 二进制' ;;
    'The opencode binary was not found (it may have been installed in another way, uninstall it manually)') printf '%s' '未找到 opencode 二进制（可能通过其他方式安装，请手动卸载）' ;;
    'The configuration directory is kept: ~/.config/opencode (you can delete it manually)') printf '%s' '配置目录保留：~/.config/opencode（可手动删除）' ;;
    'Install OpenCode (the terminal AI coding assistant, default action)') printf '%s' '安装 OpenCode（终端 AI 编程助手，默认动作）' ;;
    '🤖 Installing Pi (the AI coding agent framework, pi.dev)') printf '%s' '🤖 安装 Pi（AI 编程代理框架，pi.dev）' ;;
    'Pi detected (%s)') printf '%s' '检测到已安装 Pi（%s）' ;;
    'The official installation script failed, check the network or see https://pi.dev') printf '%s' '官方安装脚本执行失败，请检查网络或参考 https://pi.dev' ;;
    'It has been installed to %s, but it is not in the current PATH') printf '%s' '已装到 %s，但不在当前 PATH' ;;
    'Please add it to your shell configuration:') printf '%s' '请添加到 shell 配置：' ;;
    'The pi command was not found right after the installation, reopen the terminal or check PATH') printf '%s' '安装后未立即找到 pi 命令，请重新打开终端或检查 PATH' ;;
    'It can also be installed via npm/pnpm/bun: npm install -g @earendil-works/pi-coding-agent') printf '%s' '也支持通过 npm/pnpm/bun 安装：npm install -g @earendil-works/pi-coding-agent' ;;
    '🎉 Pi installation complete!') printf '%s' '🎉 Pi 安装完成！' ;;
    'Start an interactive TUI session') printf '%s' '启动交互式 TUI 会话' ;;
    'fix this bug           # give the prompt directly') printf '%s' '修复这个 bug'\''           # 直接给提示' ;;
    'Configure the model / API key and the extensions: see https://pi.dev') printf '%s' '配置模型/API Key 与扩展：参考 https://pi.dev' ;;
    'Delete %s/.pi (with the configuration and the extensions)'\?) printf '%s' '是否删除 %s/.pi（含配置与扩展）？' ;;
    'Deleted %s/.pi') printf '%s' '已删除 %s/.pi' ;;
    'The Pi binary was not found (it may have been installed globally with npm, uninstall it with npm uninstall -g @earendil-works/pi-coding-agent)') printf '%s' '未找到 Pi 二进制（可能通过 npm 全局安装，请用 npm uninstall -g @earendil-works/pi-coding-agent 卸载）' ;;
    'Install Pi (the AI coding agent framework, default action)') printf '%s' '安装 Pi（AI 编程代理框架，默认动作）' ;;
    *) return 1 ;;
  esac
}
